#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int val;
    int idx;
} Element;

int cmp(const void *a, const void *b) {
    Element *ea = (Element *)a;
    Element *eb = (Element *)b;
    if (ea->val != eb->val) {
        return (ea->val < eb->val) ? -1 : 1;
    }
    return ea->idx - eb->idx;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *raw = (int *)malloc((n + 2) * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &raw[i]);
    }

    // Comprimir elementos consecutivos iguais
    int *a = (int *)malloc((n + 2) * sizeof(int));
    int m = 0;
    a[0] = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || raw[i] != raw[i - 1]) {
            m++;
            a[m] = raw[i];
        }
    }
    a[m + 1] = 0;
    free(raw);

    Element *elements = (Element *)malloc(m * sizeof(Element));
    for (int i = 1; i <= m; i++) {
        elements[i - 1].val = a[i];
        elements[i - 1].idx = i;
    }

    qsort(elements, m, sizeof(Element), cmp);

    // active[i] indica se o retângulo i ainda é mais alto que o corte atual
    char *active = (char *)calloc(m + 2, sizeof(char));
    for (int i = 1; i <= m; i++) {
        active[i] = 1;
    }

    int current_components = 1;
    int max_pieces = current_components + 1;

    int i = 0;
    while (i < m) {
        int j = i;
        // Encontrar todos os elementos com a mesma altura
        while (j < m && elements[j].val == elements[i].val) {
            j++;
        }

        // Para todos com esta altura, calcular o impacto ao desativá-los
        for (int k = i; k < j; k++) {
            int idx = elements[k].idx;
            int left_active = active[idx - 1];
            int right_active = active[idx + 1];

            if (left_active && right_active) {
                current_components++;
            } else if (!left_active && !right_active) {
                current_components--;
            }
        }

        // Marcar como inativos
        for (int k = i; k < j; k++) {
            active[elements[k].idx] = 0;
        }

        // Se ainda restarem componentes acima do corte
        if (current_components > 0) {
            int pieces = current_components + 1;
            if (pieces > max_pieces) {
                max_pieces = pieces;
            }
        }

        i = j;
    }

    printf("%d\n", max_pieces);

    free(a);
    free(elements);
    free(active);

    return 0;
}
