    Rectangle *r1 = (Rectangle *)a;
    Rectangle *r2 = (Rectangle *)b;
    if (r2->height != r1->height) {
        return (r2->height > r1->height) ? 1 : -1;
    }
    return r1->index - r2->index;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Rectangle *rects = (Rectangle *)malloc(n * sizeof(Rectangle));
    for (int i = 0; i < n; i++) {
        scanf("%d", &rects[i].height);
        rects[i].index = i;
    }

    qsort(rects, n, sizeof(Rectangle), compare);

    bool *active = (bool *)calloc(n, sizeof(bool));
    int current_components = 0;
    int max_pieces = 1;

    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && rects[j].height == rects[i].height) {
            int idx = rects[j].index;
            active[idx] = true;

            bool left = (idx > 0 && active[idx - 1]);
            bool right = (idx < n - 1 && active[idx + 1]);

            if (!left && !right) {
                current_components++;
            } else if (left && right) {
                current_components--;
            }
            j++;
        }

        int pieces = 1 + current_components;
        if (pieces > max_pieces) {
            max_pieces = pieces;
        }

        i = j;
    }

    printf("%d\n", max_pieces);

    free(rects);
    free(active);

